using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具库（ScriptableObject）— 所有道具生成的中央管理入口。
/// 右键 -> Create -> Game -> Items Library 创建。
///
/// 核心机制:
///   1. 不放回抽取：道具每一局只能生成一次，已生成的从池中移除
///   2. 池空自动重置：所有道具都被抽取后，重新从母本拷贝
///   3. 品质加权随机：先按权重随机出品质 → 再从该品质中等概率选一个
///   4. 优先池机制：RoomConfig.itemPool 作为优先池，从中均匀随机选道具，
///      若该道具在 Library 池中可用则直接取出，否则回退到品质加权随机
///   5. 集成 ItemPoolFilter（过滤玩家已达上限的道具）
/// </summary>
[CreateAssetMenu(fileName = "ItemsLibrary", menuName = "Game/Items Library")]
public class ItemsLibrary : ScriptableObject
{
    [Header("道具预制体")]
    [Tooltip("全量道具预制体列表（每个须挂载 ItemPickup 组件）")]
    [SerializeField] private List<GameObject> _itemPrefabs;

    [Header("默认品质权重")]
    [Tooltip("全局默认品质生成权重。RoomConfig 可覆盖。")]
    [SerializeField] private QualityWeight[] _defaultQualityWeights = new[]
    {
        new QualityWeight { quality = ItemQuality.Common,    weight = 50f },
        new QualityWeight { quality = ItemQuality.Uncommon,  weight = 30f },
        new QualityWeight { quality = ItemQuality.Rare,      weight = 15f },
        new QualityWeight { quality = ItemQuality.Legendary, weight = 5f  },
    };

    /// <summary>全量道具预制体（只读）</summary>
    public IReadOnlyList<GameObject> AllItemPrefabs => _itemPrefabs;

    /// <summary>默认品质权重（只读）</summary>
    public IReadOnlyList<QualityWeight> DefaultQualityWeights => _defaultQualityWeights;

    /// <summary>当前可用水池数量</summary>
    public int AvailableCount => _availablePool != null ? _availablePool.Count : 0;

    // ========== 运行时状态 ==========

    /// <summary>运行时可用水池（不放回抽取，池空自动重置）</summary>
    private List<GameObject> _availablePool;

    /// <summary>标记运行时是否已初始化</summary>
    private bool _initialized;

    /// <summary>局内品质权重偏移（道具效果可动态修改，ResetPool 时清除）</summary>
    private Dictionary<ItemQuality, float> _qualityWeightOffsets;

    /// <summary>局内被禁品质（道具效果可永久移除某品质，池空重置也不添加，新一局清除）</summary>
    private HashSet<ItemQuality> _bannedQualities;

    // ========== 静态访问 ==========

    private static ItemsLibrary _instance;

    /// <summary>
    /// 从 Resources 加载的全局实例（缓存）。
    /// 资产路径：Resources/TestAssets/ItemsLibrary.asset
    /// </summary>
    public static ItemsLibrary Instance
    {
        get
        {
            if (_instance == null)
                _instance = Resources.Load<ItemsLibrary>("TestAssets/ItemsLibrary");
            return _instance;
        }
    }

    // ========== 生命周期 ==========

    /// <summary>
    /// 进入 Play Mode 时重置道具池。
    /// 确保 Domain Reloading 禁用时上一局的状态不会残留。
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void OnPlayModeStart()
    {
        // 强制重新加载实例并重置（Domain Reloading 禁用时 _instance 可能残留旧引用）
        _instance = Resources.Load<ItemsLibrary>("TestAssets/ItemsLibrary");
        if (_instance != null)
            _instance.ResetPool();
    }

    /// <summary>确保运行时池已初始化</summary>
    private void EnsureInitialized()
    {
        if (_initialized) return;
        ResetPool();
    }

    /// <summary>
    /// 重置道具池 — 从母本拷贝全量道具。
    /// 供游戏流程在新一局开始时调用。
    /// </summary>
    public void ResetPool()
    {
        _bannedQualities = new HashSet<ItemQuality>();
        _qualityWeightOffsets = new Dictionary<ItemQuality, float>();
        RebuildPool();
        _initialized = true;
    }

    /// <summary>
    /// 从母本重建可用水池，排除被禁品质。不清除禁集和偏移。
    /// 供池空自动重置和 ResetPool 共用。
    /// </summary>
    private void RebuildPool()
    {
        _availablePool = new List<GameObject>();
        if (_itemPrefabs == null) return;

        foreach (var prefab in _itemPrefabs)
        {
            if (prefab == null) continue;
            if (_bannedQualities != null && _bannedQualities.Count > 0)
            {
                var pickup = prefab.GetComponent<ItemPickup>();
                if (pickup != null && pickup.itemData != null && _bannedQualities.Contains(pickup.itemData.quality))
                    continue;
            }
            _availablePool.Add(prefab);
        }
    }

    // ========== 核心 API ==========

    /// <summary>
    /// 抽取一个道具预制体（不放回）。
    ///
    /// 优先池逻辑：
    ///   1. 若 preferredPool 非空，从中均匀随机选一个，并弹出
    ///   2. 尝试从 Library 池中取出该道具（TryGetSpecific）
    ///   3. 若 Library 池中没有（已被生成过），回退到品质加权随机
    ///
    /// 若 preferredPool 为空，直接品质加权随机。
    /// 池空自动重置。
    /// </summary>
    /// <param name="preferredPool">优先池（RoomConfig.itemPool），null 则用全池加权随机</param>
    /// <param name="weights">品质权重覆盖（null 则用默认权重）</param>
    /// <param name="filter">ItemManager 用于过滤已达上限的道具（null 则不过滤）</param>
    public GameObject GetRandomItemPrefab(
        IList<GameObject> preferredPool = null,
        QualityWeight[] weights = null,
        ItemManager filter = null)
    {
        var list = GetRandomItemPrefabs(1, preferredPool, weights, filter);
        return list.Count > 0 ? list[0] : null;
    }

    /// <summary>
    /// 抽取 N 个不重复的道具预制体（不放回）。
    ///
    /// 优先池逻辑（每次独立）：
    ///   1. 若 preferredPool 副本非空，从中均匀随机选一个并弹出
    ///   2. 尝试从 Library 池中取出该道具
    ///   3. 若不可用，回退到品质加权随机
    ///
    /// 池空自动重置继续抽取。
    /// </summary>
    public List<GameObject> GetRandomItemPrefabs(
        int count,
        IList<GameObject> preferredPool = null,
        QualityWeight[] weights = null,
        ItemManager filter = null)
    {
        EnsureInitialized();

        var result = new List<GameObject>();

        // 拷贝优先池（运行时可修改，不影响 RoomConfig 原始数据）
        var remaining = (preferredPool != null && preferredPool.Count > 0)
            ? new List<GameObject>(preferredPool)
            : null;

        for (int i = 0; i < count; i++)
        {
            GameObject picked = null;

            // 1. 尝试从优先池中选
            if (remaining != null && remaining.Count > 0)
            {
                int idx = Random.Range(0, remaining.Count);
                var preferred = remaining[idx];
                remaining.RemoveAt(idx); // 弹出（无论是否成功取出）

                // 尝试从 Library 池中取出该指定道具
                picked = TryGetSpecific(preferred, filter);
            }

            // 2. 优先池不可用或无优先池 → 品质加权随机
            if (picked == null)
                picked = WeightedRandomDraw(weights, filter);

            if (picked == null) break;
            result.Add(picked);
        }

        return result;
    }

    // ========== 局内权重偏移 API ==========

    /// <summary>
    /// 对指定品质的生成权重施加偏移（累加，可正可负）。
    /// 最终权重 = 原始权重 + 偏移，clamp 到 ≥0。
    /// 供道具效果在局内动态修改品质出现概率。
    /// </summary>
    public void ApplyQualityWeightOffset(ItemQuality quality, float delta)
    {
        EnsureInitialized();
        if (!_qualityWeightOffsets.ContainsKey(quality))
            _qualityWeightOffsets[quality] = 0f;
        _qualityWeightOffsets[quality] += delta;
    }

    /// <summary>
    /// 禁用指定品质 — 立即从可用水池移除该品质所有道具，
    /// 且本局内池空重置也不添加该品质道具。新一局 ResetPool 时清除。
    /// </summary>
    public void BanQuality(ItemQuality quality)
    {
        EnsureInitialized();
        if (_bannedQualities == null) _bannedQualities = new HashSet<ItemQuality>();
        _bannedQualities.Add(quality);

        if (_availablePool != null)
        {
            _availablePool.RemoveAll(prefab =>
            {
                if (prefab == null) return true;
                var pickup = prefab.GetComponent<ItemPickup>();
                return pickup != null && pickup.itemData != null && pickup.itemData.quality == quality;
            });
        }
    }

    // ========== 内部方法 ==========

    /// <summary>
    /// 尝试从 _availablePool 中取出指定预制体（不放回）。
    /// 检查 maxCount 过滤。不可用则返回 null。
    /// </summary>
    private GameObject TryGetSpecific(GameObject prefab, ItemManager filter)
    {
        if (prefab == null || _availablePool == null || !_availablePool.Contains(prefab))
            return null;

        // maxCount 过滤
        if (filter != null)
        {
            var pickup = prefab.GetComponent<ItemPickup>();
            if (pickup != null && pickup.itemData != null)
            {
                int maxCount = pickup.itemData.maxCount;
                if (maxCount > 0 && filter.GetItemCount(pickup.itemData.itemId) >= maxCount)
                    return null;
            }
        }

        _availablePool.Remove(prefab);
        return prefab;
    }

    /// <summary>
    /// 品质加权随机抽取一个道具（不放回），处理池空重置。
    /// </summary>
    private GameObject WeightedRandomDraw(QualityWeight[] weights, ItemManager filter)
    {
        var candidates = ResolveCandidates(filter);

        // 池空 → 重建（保留禁品质和偏移）
        if (candidates == null || candidates.Count == 0)
        {
            RebuildPool();
            candidates = ResolveCandidates(filter);
            if (candidates == null || candidates.Count == 0) return null;
        }

        var resolvedWeights = weights ?? _defaultQualityWeights;
        var picked = WeightedRandomPick(candidates, resolvedWeights);
        if (picked != null)
            _availablePool.Remove(picked);
        return picked;
    }

    /// <summary>
    /// 计算当前可用候选列表（全池 + maxCount 过滤）。
    /// </summary>
    private List<GameObject> ResolveCandidates(ItemManager filter)
    {
        if (_availablePool == null || _availablePool.Count == 0) return null;

        var candidates = new List<GameObject>(_availablePool);

        if (filter != null)
            candidates = ItemPoolFilter.GetAvailablePool(candidates, filter);

        return candidates;
    }

    /// <summary>
    /// 品质加权随机选取（不修改池，仅选取）：
    /// 1. 按品质分组
    /// 2. 仅考虑有道具的品质，按权重归一化随机出品质
    /// 3. 从该品质组中等概率随机选一个
    /// </summary>
    private GameObject WeightedRandomPick(IList<GameObject> candidates, IReadOnlyList<QualityWeight> weights)
    {
        // 按品质分组
        var groups = new Dictionary<ItemQuality, List<GameObject>>();
        foreach (var prefab in candidates)
        {
            if (prefab == null) continue;
            var pickup = prefab.GetComponent<ItemPickup>();
            if (pickup == null || pickup.itemData == null) continue;
            var q = pickup.itemData.quality;
            if (!groups.ContainsKey(q))
                groups[q] = new List<GameObject>();
            groups[q].Add(prefab);
        }

        if (groups.Count == 0) return null;

        // 构建有效品质权重表（仅含有道具的品质）
        var validQualities = new List<ItemQuality>();
        var validWeights = new List<float>();
        float totalWeight = 0f;

        foreach (var w in weights)
        {
            if (w.weight <= 0f) continue;
            if (!groups.ContainsKey(w.quality) || groups[w.quality].Count == 0) continue;

            // 应用局内权重偏移
            float finalWeight = w.weight;
            if (_qualityWeightOffsets != null && _qualityWeightOffsets.TryGetValue(w.quality, out var offset))
                finalWeight = Mathf.Max(0f, w.weight + offset);

            if (finalWeight <= 0f) continue; // 偏移后权重归零 → 跳过该品质

            validQualities.Add(w.quality);
            validWeights.Add(finalWeight);
            totalWeight += finalWeight;
        }

        // 所有配置权重对应的品质都无道具 → 从所有有道具的品质中等概率选
        if (totalWeight <= 0f)
        {
            var allKeys = new List<ItemQuality>(groups.Keys);
            var q = allKeys[Random.Range(0, allKeys.Count)];
            var g = groups[q];
            return g[Random.Range(0, g.Count)];
        }

        // 按权重随机出品质
        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        ItemQuality rolledQuality = validQualities[0];

        for (int i = 0; i < validQualities.Count; i++)
        {
            cumulative += validWeights[i];
            if (roll <= cumulative)
            {
                rolledQuality = validQualities[i];
                break;
            }
        }

        // 从该品质组中等概率随机选一个
        var group = groups[rolledQuality];
        return group[Random.Range(0, group.Count)];
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具生成器 — 从道具池中随机生成道具
/// </summary>
public class ItemSpawner : MonoBehaviour
{
    [Header("道具池")]
    [Tooltip("引用房间配置")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public GameObject[] manualItemPool;
    public int manualMinItems = 1;
    public int manualMaxItems = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    private bool _hasSpawned;

    /// <summary>生成道具</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var library = ItemsLibrary.Instance;
        if (library == null)
        {
            Debug.LogWarning("[ItemSpawner] ItemsLibrary 未找到，跳过生成");
            return;
        }

        // 确定池和权重
        var pool = (roomConfig != null && roomConfig.itemPool != null && roomConfig.itemPool.Count > 0)
            ? roomConfig.itemPool
            : (manualItemPool != null && manualItemPool.Length > 0 ? new List<GameObject>(manualItemPool) : null);
        var weights = (roomConfig != null && roomConfig.qualityWeights != null && roomConfig.qualityWeights.Length > 0)
            ? roomConfig.qualityWeights
            : null;
        var filter = ItemPoolFilter.GetPlayerItemManager();

        int min = roomConfig != null ? roomConfig.minItems : manualMinItems;
        int max = roomConfig != null ? roomConfig.maxItems : manualMaxItems;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;

        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 随机洗牌生成点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        var picked = library.GetRandomItemPrefabs(count, pool, weights, filter);
        for (int i = 0; i < picked.Count; i++)
        {
            if (picked[i] == null) continue;
            Instantiate(picked[i], spawnPoints[indices[i]].position, Quaternion.identity, transform);
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具管理器 — 管理玩家当前持有的所有道具。
/// 挂载在 Player GameObject 上，通过 PlayerManager 的持久化机制自动跟随跨场景。
///
/// 核心职责:
///   1. 管理道具集合（添加/移除/查询/丢弃/转移）
///   2. 执行道具效果（OnAcquire / OnRemove）
///   3. 通知事件（供 UI Controller 监听）
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("丢弃配置")]
    [SerializeField] private GameObject _itemDropPrefab; // 丢弃道具时生成的拾取物预制体

    [Header("调试")]
    [SerializeField] private List<ItemData> _initialItems; // Inspector 调试用

    private readonly List<ItemData> _items = new List<ItemData>();
    private readonly Dictionary<string, ItemData> _itemDict = new Dictionary<string, ItemData>();
    private readonly Dictionary<string, int> _itemCounts = new Dictionary<string, int>();

    /// <summary>当前道具列表（只读），每种道具只出现一次</summary>
    public IReadOnlyList<ItemData> Items => _items;

    /// <summary>道具种类数量</summary>
    public int Count => _items.Count;

    // ========== 事件 ==========

    /// <summary>道具获得: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>道具移除: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    /// <summary>道具丢弃: (itemData, worldPosition)</summary>
    public event Action<ItemData, Vector3> OnItemDropped;

    /// <summary>道具转移: 从 (fromOwner, itemData) 转移到 (toOwner, itemData)</summary>
    public static event Action<ItemManager, ItemManager, ItemData> OnItemTransferred;

    /// <summary>任意道具被获取后触发（供 Buff 检查三件套等）</summary>
    public static event Action<GameObject> OnAnyItemAcquired;

    // ========== Unity 生命周期 ==========

    private void Start()
    {
        // Inspector 调试：自动获得初始道具
        foreach (var item in _initialItems)
        {
            if (item != null)
                AcquireItem(item);
        }
    }

    // ========== 核心方法 ==========

    /// <summary>
    /// 获得道具 — 每次获取都执行效果（支持叠加）。
    /// maxCount=0 表示无上限。
    /// </summary>
    public bool AcquireItem(ItemData item)
    {
        if (item == null) return false;

        int max = item.maxCount;
        bool hasItem = _itemDict.ContainsKey(item.itemId);
        int currentCount = hasItem ? _itemCounts[item.itemId] : 0;

        // 达到上限
        if (max > 0 && currentCount >= max)
            return false;

        // 每次获取都执行效果
        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = currentCount + 1;
        }

        OnItemAcquired?.Invoke(item);
        OnAnyItemAcquired?.Invoke(gameObject);
        return true;
    }

    /// <summary>
    /// 移除道具 — 每次移除都执行清理（支持叠加效果逐层移除）。
    /// 数量归零时从集合移除。
    /// </summary>
    public bool RemoveItem(string itemId)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次移除都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具 — 在世界坐标生成可拾取的掉落物。
    /// 与 RemoveItem 的区别：丢弃会在场景中生成 ItemPickup GameObject。
    /// </summary>
    public bool DropItem(string itemId, Vector3 worldPosition)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次丢弃都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 在世界坐标生成掉落物
        SpawnItemPickup(item, worldPosition);

        OnItemDropped?.Invoke(item, worldPosition);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具在玩家脚下
    /// </summary>
    public bool DropItemAtPlayer(string itemId)
    {
        return DropItem(itemId, transform.position + (Vector3)(UnityEngine.Random.insideUnitCircle * 0.5f));
    }

    /// <summary>
    /// 将道具转移给另一个拥有者。
    /// 从当前所有者的集合移除，添加到目标所有者的集合。
    /// 用于交易 / 队友共享道具等场景。
    /// </summary>
    public bool TransferItem(string itemId, ItemManager targetOwner)
    {
        if (targetOwner == null || !_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 目标不能已有同 ID 道具且已达上限
        if (targetOwner.HasItem(itemId))
        {
            int targetMax = item.maxCount;
            int targetCount = targetOwner.GetItemCount(itemId);
            if (targetMax > 0 && targetCount >= targetMax)
                return false;
        }

        // 从当前所有者移除一份
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            item.effect?.OnRemove(gameObject);
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 添加到目标
        targetOwner.AcquireItemInternal(item);

        OnItemTransferred?.Invoke(this, targetOwner, item);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>内部获得道具（供 TransferItem 使用）</summary>
    private void AcquireItemInternal(ItemData item)
    {
        bool hasItem = _itemDict.ContainsKey(item.itemId);

        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = _itemCounts[item.itemId] + 1;
        }

        OnItemAcquired?.Invoke(item);
    }

    /// <summary>是否有指定道具</summary>
    public bool HasItem(string itemId) => _itemDict.ContainsKey(itemId);

    /// <summary>获取道具</summary>
    public ItemData GetItem(string itemId)
        => _itemDict.TryGetValue(itemId, out var item) ? item : null;

    /// <summary>获取道具持有数量（不存在返回0）</summary>
    public int GetItemCount(string itemId)
        => _itemCounts.TryGetValue(itemId, out var count) ? count : 0;

    // ========== 私有方法 ==========

    /// <summary>在指定世界位置生成可拾取的道具掉落物</summary>
    private void SpawnItemPickup(ItemData item, Vector3 position)
    {
        GameObject prefab = _itemDropPrefab;
        if (prefab == null)
        {
            // 如果没有配置掉落预制体，创建一个默认的
            prefab = CreateDefaultPickup();
        }

        GameObject go = Instantiate(prefab, position, Quaternion.identity);
        go.name = $"ItemPickup_{item.itemId}";

        var pickup = go.GetComponent<ItemPickup>();
        if (pickup == null)
            pickup = go.AddComponent<ItemPickup>();
        pickup.itemData = item;
    }

    /// <summary>创建默认拾取物预制体（运行时兜底）</summary>
    private GameObject CreateDefaultPickup()
    {
        var go = new GameObject("DefaultItemPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(ItemPickup));
        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = null; // 使用默认图标
        sr.drawMode = SpriteDrawMode.Simple;
        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.5f;
        return go;
    }
}

using UnityEngine;

/// <summary>
/// 道具拾取物 — 场景中可拾取的道具 GameObject。
///
/// 交互方式 (近距离按键):
///   1. 玩家靠近时高亮显示 + 弹出详情 UI
///   2. 按 F 键拾取
///   3. 不再通过碰撞自动拾取
/// </summary>
public class ItemPickup : MonoBehaviour
{
    [Header("道具数据")]
    public ItemData itemData;

    [Header("交互距离")]
    [Tooltip("玩家可交互的最大距离")]
    public float pickupRadius = 1.5f;

    [Header("表现")]
    public GameObject pickupEffectPrefab;

    [Header("漂浮动画")]
    [SerializeField] private bool _enableFloatAnimation = true;
    [SerializeField] private float _floatAmplitude = 0.15f;
    [SerializeField] private float _floatFrequency = 2f;
    [SerializeField] private bool _enableRotation = true;
    [SerializeField] private float _rotationSpeed = 30f;

    [Header("高亮")]
    [SerializeField] private float _highlightScale = 1.3f;
    [SerializeField] private Color _highlightTint = new Color(1f, 1f, 0.7f, 1f);

    /// <summary>当前是否在玩家交互范围内</summary>
    public bool IsInRange { get; private set; }

    /// <summary>是否为商店商品（靠近时走购买流程而非拾取）</summary>
    public bool IsShopItem { get; set; }

    /// <summary>商店价格（从 ItemData.price 读取，应用全局折扣）</summary>
    public int ShopPrice
    {
        get
        {
            int basePrice = itemData != null ? itemData.price : 10;
            float discount = ShopManager.GlobalDiscount;
            if (discount > 0f)
                return Mathf.Max(1, Mathf.RoundToInt(basePrice * (1f - discount)));
            return basePrice;
        }
    }

    private Vector3 _startPosition;
    private SpriteRenderer _spriteRenderer;
    private Color _baseColor;
    private Vector3 _baseScale;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
        _startPosition = transform.position;
        _baseScale = transform.localScale;

        if (_spriteRenderer != null)
        {
            _baseColor = _spriteRenderer.color;

            if (itemData != null && itemData.icon != null)
                _spriteRenderer.sprite = itemData.icon;
        }
    }

    private void Update()
    {
        float t = Time.time * _floatFrequency;
        Vector3 floatOffset = _enableFloatAnimation
            ? Vector3.up * (Mathf.Sin(t) * _floatAmplitude)
            : Vector3.zero;

        // 高亮（始终运行）
        if (IsInRange)
        {
            transform.localScale = _baseScale * _highlightScale;
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_baseColor, _highlightTint, 0.5f);
        }
        else
        {
            transform.localScale = Vector3.Lerp(transform.localScale, _baseScale, Time.deltaTime * 8f);
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_spriteRenderer.color, _baseColor, Time.deltaTime * 8f);
        }

        // 漂浮位移（仅 _enableFloatAnimation 时生效）
        transform.position = _startPosition + floatOffset;

        // 旋转（仅 _enableRotation 时生效）
        if (_enableRotation)
            transform.Rotate(Vector3.forward, _rotationSpeed * Time.deltaTime);
    }

    /// <summary>由 ItemInteractionHandler 调用，标记在范围内</summary>
    public void SetInRange(bool inRange)
    {
        IsInRange = inRange;
    }

    /// <summary>执行拾取 — 返回道具数据</summary>
    public ItemData Pickup()
    {
        if (pickupEffectPrefab != null)
            Instantiate(pickupEffectPrefab, transform.position, Quaternion.identity);

        return itemData;
    }

    /// <summary>品质 → 颜色映射</summary>
    public static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("货币掉落")]
    [SerializeField] private int _currencyPerEnemy = 3;
    [SerializeField] private Sprite _currencyIcon;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        // 自动加载货币图标
        if (_currencyIcon == null)
            _currencyIcon = Resources.Load<Sprite>("TestAssets/Icons/icon_atp");

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = roomRoot.config.maxEnemies == 0? true : false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        // Shop 房间特殊处理：开张商店
        if (roomRoot.config.roomType == RoomType.Shop)
        {
            if (_isFirstEnter)
            {
                _isFirstEnter = false;
                OpenShopRoom();
            }
            return;
        }

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;

            // 统计：首次进入房间
            GameStatistics.Instance?.RecordRoomVisited(roomRoot.config.roomType);

            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
            else
            {
                // 无怪物的房间（如 Start 房）：直接生成道具
                SpawnItems();
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 道具现在是普通 ItemPickup，离开后保留在地图中
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)，跳过隐藏墙</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null && portal.HiddenWallHP <= 0)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;
        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        // 生成货币掉落
        SpawnCurrency(enemy.transform.position, _currencyPerEnemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>
    /// 注册一个敌人到房间存活列表（亡语分裂/召唤生成的敌人也调用此方法），
    /// 否则亡语怪不计入 _aliveEnemies 会导致房间门提前开启。
    /// </summary>
    public void RegisterEnemy(GameObject enemy)
    {
        if (enemy == null || _aliveEnemies.Contains(enemy)) return;

        _aliveEnemies.Add(enemy);

        if (enemy.TryGetComponent<IEnemy>(out var ienemy))
        {
            ienemy.OnDied += () => OnEnemyDied(enemy);
            ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();
        // 激活相邻隐藏房的门 (变为可破坏状态)
        ActivateHiddenWalls();

        // 生成道具奖励
        SpawnItems();

        // Boss/Exit 房生成下一层出口
        TrySpawnNextLevelExit();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");

        // 统计：清空房间
        GameStatistics.Instance?.RecordRoomCleared(roomRoot.config.roomType);

        OnRoomCleared?.Invoke();
    }

    /// <summary>Boss/Exit 房清空后在房间中心生成下一层出口</summary>
    private void TrySpawnNextLevelExit()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var roomType = roomRoot.config.roomType;
        if (roomType != RoomType.Boss && roomType != RoomType.Exit) return;

        var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
        if (mapConfigAsset == null) return;

        var exitGo = Instantiate(mapConfigAsset.nextLevelExitPrefab, roomRoot.Center, Quaternion.identity, transform);
        exitGo.name = "NextLevelExit";

        var exitComp = exitGo.GetComponent<NextLevelExit>();
        if (exitComp == null)
        {
            Debug.LogError("RoomManager: nextLevelExitPrefab 上没有挂载 NextLevelExit 组件，请在预制体上添加该脚本");
            return;
        }
        exitComp.nextSceneName = mapConfigAsset.nextSceneName;

        Debug.Log($"RoomManager: 房间 {roomRoot.roomId} 生成下一层出口 -> {mapConfigAsset.nextSceneName}");
    }

    /// <summary>激活通往相邻隐藏房的门</summary>
    private void ActivateHiddenWalls()
    {
        if (roomRoot == null) return;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph == null) return;

        var node = graph.GetNode(roomRoot.roomId);
        if (node == null) return;

        foreach (var conn in node.connections)
        {
            var targetNode = graph.GetNode(conn.Key);
            if (targetNode == null || targetNode.roomType != RoomType.Hidden) continue;

            // 找到指向隐藏房的门 Portal
            var portals = GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                if (portal.targetRoomId == conn.Key && portal.HiddenWallHP > 0)
                {
                    portal.SetBreakable();
                    break;
                }
            }
        }
    }

    /// <summary>生成道具</summary>
    private void SpawnItems()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;

        int totalItems = Random.Range(cfg.minItems, cfg.maxItems + 1);
        int spawnPointCount = roomRoot.itemSpawnPoints != null ? roomRoot.itemSpawnPoints.Length : 0;
        if (spawnPointCount == 0) return;

        int spawnCount = Mathf.Min(totalItems, spawnPointCount);

        var library = ItemsLibrary.Instance;
        if (library == null)
        {
            Debug.LogWarning("[RoomManager] ItemsLibrary 未找到，跳过道具生成");
            return;
        }

        // 确定池和权重：RoomConfig 覆盖优先
        var pool = (cfg.itemPool != null && cfg.itemPool.Count > 0) ? cfg.itemPool : null;
        var weights = (cfg.qualityWeights != null && cfg.qualityWeights.Length > 0) ? cfg.qualityWeights : null;
        var filter = ItemPoolFilter.GetPlayerItemManager();

        var picked = library.GetRandomItemPrefabs(spawnCount, pool, weights, filter);
        for (int i = 0; i < picked.Count && i < spawnPointCount; i++)
        {
            if (picked[i] == null) continue;
            Instantiate(picked[i], roomRoot.itemSpawnPoints[i].position, Quaternion.identity, transform);
        }
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    // ==================== Shop 房间 ====================

    /// <summary>开张商店</summary>
    private void OpenShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager == null)
        {
            Debug.LogWarning($"[RoomManager] Room{roomRoot.roomId}: Shop 房间但未挂载 ShopManager 组件");
            return;
        }

        shopManager.OpenShop();
    }

    /// <summary>打烊商店</summary>
    private void CloseShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager != null)
            shopManager.CloseShop();
    }

    /// <summary>在指定位置生成货币掉落物</summary>
    private void SpawnCurrency(Vector3 position, int amount)
    {
        var go = new GameObject("CurrencyPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(CurrencyPickup));

        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = _currencyIcon;
        sr.sortingOrder = 5;

        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.4f;

        var pickup = go.GetComponent<CurrencyPickup>();
        pickup.amount = amount;

        // 随机散布
        position += (Vector3)(Random.insideUnitCircle * 0.5f);
        go.transform.position = position;
        go.transform.SetParent(transform);
    }
}

