/// <summary>
/// 道具品质等级。
/// 参考: 以撒的结合 / 崩坏星穹铁道奇物 / 明日方舟藏品。
/// </summary>
public enum ItemQuality
{
    /// <summary>白色 — 普通</summary>
    Common,

    /// <summary>蓝色 — 稀有</summary>
    Uncommon,

    /// <summary>紫色 — 史诗</summary>
    Rare,

    /// <summary>橙色 — 传说</summary>
    Legendary
