/// <summary>
/// 道具移除节点的 Screen Space Overlay 浮动提示 — 与商店弹窗同款。
/// 跟随世界坐标，CanvasGroup 淡入淡出，深色半透明背景。
/// 挂在 Canvas 下的空 GameObject 上。
/// </summary>
public class ItemRemoverPrompt : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private CanvasGroup _canvasGroup;
    [SerializeField] private Image _background;
    [SerializeField] private TMP_Text _promptText;

    [Header("样式")]
    [SerializeField] private float _fadeSpeed = 10f;
    [SerializeField] private Vector2 _screenOffset = new Vector2(0, 60f);

    private RectTransform _rect;
    private Camera _mainCam;
    private Transform _target;
    private bool _visible;

    private void Awake()
    {
        _rect = GetComponent<RectTransform>();
        _mainCam = Camera.main;
        if (_canvasGroup != null) _canvasGroup.alpha = 0f;
        // 注意：不要在 Awake 里 SetActive(false)。
        // 该对象在场景中初始为 inactive，首次 Show() 的 SetActive(true)
        // 才会触发 Awake，若此处再 SetActive(false) 会导致首次提示不显示。
    }

    public void Show(Transform target)
    {
        if (target == null) return;

        _target = target;
        gameObject.SetActive(true);
        _visible = true;

        if (_promptText != null)
            _promptText.text = "点击F键移除道具";
        if (_background != null)
            _background.color = new Color(0.05f, 0.05f, 0.1f, 0.92f);
    }

    public void Hide()
    {
        _target = null;
        _visible = false;
        gameObject.SetActive(false);
    }

    private void LateUpdate()
    {
        if (_target == null || !_visible)
        {
            if (_canvasGroup != null && _canvasGroup.alpha > 0f)
                _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 0f, _fadeSpeed * Time.deltaTime);
            return;
        }

        if (_mainCam != null)
        {
            Vector3 screenPos = _mainCam.WorldToScreenPoint(_target.position);
            _rect.position = screenPos + (Vector3)_screenOffset;
        }

        if (_canvasGroup != null)
            _canvasGroup.alpha = Mathf.MoveTowards(_canvasGroup.alpha, 1f, _fadeSpeed * Time.deltaTime);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具池过滤工具 — 道具刷新时排除玩家已达拾取上限的道具。
/// 玩家持有某道具数量 >= ItemData.maxCount（且 maxCount>0）时，该道具不再从池中刷新。
/// 供 ItemSpawner（房间刷新）与 ShopManager（商店开张）共用。
/// </summary>
public static class ItemPoolFilter
{
    /// <summary>
    /// 过滤道具池：移除玩家已达上限的道具预制体。返回过滤后的新列表。
    /// itemManager 为空或池为空时原样返回。
    /// </summary>
    public static List<GameObject> GetAvailablePool(IList<GameObject> pool, ItemManager itemManager)
    {
        if (pool == null || pool.Count == 0) return new List<GameObject>(pool ?? System.Array.Empty<GameObject>());
        if (itemManager == null) return new List<GameObject>(pool);

        var result = new List<GameObject>(pool.Count);
        foreach (var prefab in pool)
        {
            if (prefab == null) continue;

            // 从预制体上取 ItemData
            var pickup = prefab.GetComponent<ItemPickup>();
            if (pickup == null || pickup.itemData == null)
            {
                // 无法判断的道具保留（不误删）
                result.Add(prefab);
                continue;
            }

            var data = pickup.itemData;
            // 无上限（maxCount=0）或未达上限 → 保留
            if (data.maxCount <= 0 || itemManager.GetItemCount(data.itemId) < data.maxCount)
                result.Add(prefab);
        }
        return result;
    }

    /// <summary>统一获取玩家的 ItemManager（PlayerManager 持久化单例优先）</summary>
    public static ItemManager GetPlayerItemManager()
    {
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

